import React, { useState } from 'react';
import { FaUser, FaUserGraduate, FaFilter, FaSearch, FaGraduationCap, FaBed } from 'react-icons/fa';

// Composants
import Tableau from '../components/communs/Tableau';
import Recherche from '../components/communs/Recherche';
import ModalDetail from '../components/communs/ModalDetail';
import ModalFormulaire from '../components/communs/ModalFormulaire';
import Chargement from '../components/communs/Chargement';
import { BoutonAjouter, BoutonVoir, BoutonModifier, BoutonSupprimer } from '../components/communs/Boutons';
import FiltresAvances from '../components/communs/FiltresAvances';
import PageHeader from '../components/communs/PageHeader';
import DetailEtudiant from '../components/etudiants/DetailEtudiant';
import FormulaireEtudiant from '../components/etudiants/FormulaireEtudiant';
import StatistiquesEtudiant from '../components/etudiants/StatistiquesEtudiant';

// Hooks
import useDonnees from '../hooks/useDonnees';
import useTri from '../hooks/useTri';

// Styles
import { colors } from '../styles/theme';

function EtudiantPage() {
  // Données simulées pour les étudiants
  const mockEtudiants = [
    { matricule: "ETU001", nom: "Dupont", prenom: "Jean", email: "jean.dupont@univ.edu", telephone: "0612345678", n_etab: 1, n_chambre: "A101", adresse: "123 Rue de l'Université", notes: "Boursier" },
    { matricule: "ETU002", nom: "Martin", prenom: "Sophie", email: "sophie.martin@univ.edu", telephone: "0623456789", n_etab: 2, n_chambre: "B201", adresse: "45 Avenue des Sciences", notes: "" },
    { matricule: "ETU003", nom: "Bernard", prenom: "Thomas", email: "thomas.bernard@univ.edu", telephone: "0634567890", n_etab: 1, n_chambre: null, adresse: "78 Boulevard des Arts", notes: "Étudiant international" },
    { matricule: "ETU004", nom: "Petit", prenom: "Emma", email: "emma.petit@univ.edu", telephone: "0645678901", n_etab: 3, n_chambre: "C301", adresse: "12 Rue des Lettres", notes: "" },
    { matricule: "ETU005", nom: "Robert", prenom: "Lucas", email: "lucas.robert@univ.edu", telephone: "0656789012", n_etab: 2, n_chambre: null, adresse: "56 Avenue de la Recherche", notes: "Sportif de haut niveau" },
    { matricule: "ETU006", nom: "Richard", prenom: "Chloé", email: "chloe.richard@univ.edu", telephone: "0667890123", n_etab: 1, n_chambre: "A102", adresse: "89 Rue des Sciences", notes: "" },
    { matricule: "ETU007", nom: "Moreau", prenom: "Hugo", email: "hugo.moreau@univ.edu", telephone: "0678901234", n_etab: 3, n_chambre: null, adresse: "34 Boulevard de l'Innovation", notes: "" },
    { matricule: "ETU008", nom: "Simon", prenom: "Léa", email: "lea.simon@univ.edu", telephone: "0689012345", n_etab: 2, n_chambre: "B202", adresse: "67 Avenue des Études", notes: "Représentante des étudiants" },
    { matricule: "ETU009", nom: "Laurent", prenom: "Nathan", email: "nathan.laurent@univ.edu", telephone: "0690123456", n_etab: 1, n_chambre: null, adresse: "23 Rue de la Connaissance", notes: "" },
    { matricule: "ETU010", nom: "Michel", prenom: "Camille", email: "camille.michel@univ.edu", telephone: "0601234567", n_etab: 3, n_chambre: "C302", adresse: "45 Boulevard du Savoir", notes: "Double cursus" },
  ];

  // Données simulées pour les établissements
  const mockEtablissements = [
    { n_etab: 1, nom_etab: "Faculté des Sciences", adresse_etab: "1 Rue des Sciences, 75001 Paris" },
    { n_etab: 2, nom_etab: "École d'Ingénieurs", adresse_etab: "2 Avenue de la Technologie, 75002 Paris" },
    { n_etab: 3, nom_etab: "Faculté de Médecine", adresse_etab: "3 Boulevard de la Santé, 75003 Paris" },
  ];

  // Données simulées pour les chambres
  const mockChambres = [
    { n_chambre: "A101", capacite_max: 2, etat_chambre: "Occupée", n_bat: 1 },
    { n_chambre: "A102", capacite_max: 1, etat_chambre: "Occupée", n_bat: 1 },
    { n_chambre: "B201", capacite_max: 3, etat_chambre: "Occupée", n_bat: 2 },
    { n_chambre: "B202", capacite_max: 1, etat_chambre: "Occupée", n_bat: 2 },
    { n_chambre: "C301", capacite_max: 2, etat_chambre: "Occupée", n_bat: 3 },
    { n_chambre: "C302", capacite_max: 2, etat_chambre: "Occupée", n_bat: 3 },
    { n_chambre: "D101", capacite_max: 4, etat_chambre: "Disponible", n_bat: 4 },
    { n_chambre: "D102", capacite_max: 1, etat_chambre: "Disponible", n_bat: 4 },
  ];
  
  // Utilisation des hooks personnalisés
  const { 
    donnees: etudiants, 
    setDonnees: setEtudiants, 
    loading, 
    error, 
    setError,
    ajouterElement,
    modifierElement,
    supprimerElement
  } = useDonnees(mockEtudiants);
  
  const { 
    donnees: etablissements 
  } = useDonnees(mockEtablissements);
  
  const { 
    donnees: chambres 
  } = useDonnees(mockChambres);
  
  const { trierDonnees } = useTri(etudiants, setEtudiants);
  
  // États locaux
  const [selectedEtudiant, setSelectedEtudiant] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [showFormModal, setShowFormModal] = useState(false);
  const [formMode, setFormMode] = useState('add'); // 'add' ou 'edit'
  const [formData, setFormData] = useState({
    matricule: '',
    nom: '',
    prenom: '',
    email: '',
    telephone: '',
    n_etab: '',
    n_chambre: '',
    adresse: '',
    notes: ''
  });
  const [filterCriteria, setFilterCriteria] = useState({
    n_etab: '',
    avecChambre: ''
  });
  const [searchTerm, setSearchTerm] = useState('');

  // Fonction de filtrage pour les étudiants
  const filtrerEtudiants = (etudiant) => {
    // Filtrage par établissement
    const matchesEtablissement = filterCriteria.n_etab === '' || 
      etudiant.n_etab.toString() === filterCriteria.n_etab;
    
    // Filtrage par statut de chambre
    const matchesChambre = filterCriteria.avecChambre === '' || 
      (filterCriteria.avecChambre === 'avec' && etudiant.n_chambre) ||
      (filterCriteria.avecChambre === 'sans' && !etudiant.n_chambre);
    
    // Recherche par nom, prénom, matricule ou email
    const matchesSearch = searchTerm === '' || 
      etudiant.nom.toLowerCase().includes(searchTerm.toLowerCase()) ||
      etudiant.prenom.toLowerCase().includes(searchTerm.toLowerCase()) ||
      etudiant.matricule.toLowerCase().includes(searchTerm.toLowerCase()) ||
      etudiant.email.toLowerCase().includes(searchTerm.toLowerCase());
  
    return matchesEtablissement && matchesChambre && matchesSearch;
  };

  // Filtrer les étudiants
  const etudiantsFiltres = etudiants.filter(filtrerEtudiants);

  // Gestionnaires d'événements
  const handleView = (etudiant) => {
    setSelectedEtudiant(etudiant);
    setShowModal(true);
  };

  const handleAdd = () => {
    setFormData({
      matricule: '',
      nom: '',
      prenom: '',
      email: '',
      telephone: '',
      n_etab: '',
      n_chambre: '',
      adresse: '',
      notes: ''
    });
    setFormMode('add');
    setShowFormModal(true);
  };

  const handleEdit = (etudiant) => {
    setFormData({
      matricule: etudiant.matricule,
      nom: etudiant.nom,
      prenom: etudiant.prenom,
      email: etudiant.email,
      telephone: etudiant.telephone || '',
      n_etab: etudiant.n_etab,
      n_chambre: etudiant.n_chambre || '',
      adresse: etudiant.adresse || '',
      notes: etudiant.notes || ''
    });
    setFormMode('edit');
    setShowFormModal(true);
  };

  const handleDelete = async (matricule) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer cet étudiant?')) {
      try {
        supprimerElement(matricule, 'matricule');
      } catch (err) {
        setError('Erreur lors de la suppression');
        console.error('Erreur:', err);
      }
    }
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'n_etab' ? parseInt(value, 10) : value
    });
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    try {
      if (formMode === 'add') {
        ajouterElement(formData);
      } else {
        modifierElement(formData.matricule, 'matricule', formData);
      }
      setShowFormModal(false);
    } catch (err) {
      setError(`Erreur lors de l'${formMode === 'add' ? 'ajout' : 'édition'}`);
      console.error('Erreur:', err);
    }
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };
  
  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilterCriteria({
      ...filterCriteria,
      [name]: value
    });
  };

  // Fonction pour obtenir le nom de l'établissement à partir de son ID
  const getEtablissementName = (n_etab) => {
    const etablissement = etablissements.find(e => e.n_etab === n_etab);
    return etablissement ? etablissement.nom_etab : `Établissement ${n_etab}`;
  };

  // Fonction pour obtenir le nom de la chambre
  const getChambreName = (n_chambre) => {
    const chambre = chambres.find(c => c.n_chambre === n_chambre);
    return chambre ? `${n_chambre} (${chambre.capacite_max} pers.)` : n_chambre;
  };

  // Définition des colonnes pour le tableau
  const colonnesEtudiant = [
    { id: 'matricule', label: 'Matricule', triable: true },
    { 
      id: 'nom_complet', 
      label: 'Nom complet', 
      triable: false, 
      rendu: (etudiant) => `${etudiant.nom} ${etudiant.prenom}` 
    },
    { id: 'email', label: 'Email', triable: true },
    { 
      id: 'n_etab', 
      label: 'Établissement', 
      triable: true, 
      rendu: (etudiant) => getEtablissementName(etudiant.n_etab) 
    },
    { 
      id: 'n_chambre', 
      label: 'Chambre', 
      triable: true, 
      rendu: (etudiant) => etudiant.n_chambre ? getChambreName(etudiant.n_chambre) : (
        <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-yellow-100 text-yellow-800">
          Non attribuée
        </span>
      )
    }
  ];

  return (
    <div className="p-4">
      <PageHeader 
        titre="Gestion des Étudiants"
        sousTitre={`${etudiantsFiltres.length} étudiant(s) trouvé(s)`}
        icone={<FaUserGraduate style={{ color: colors.primaryColor }} />}
        actionPrincipale={
          <BoutonAjouter 
            onClick={handleAdd} 
            texte="Ajouter un étudiant" 
          />
        }
        actionSecondaire={
          <Recherche 
            valeur={searchTerm}
            onChange={handleSearchChange}
            placeholder="Rechercher un étudiant..."
            width="250px"
          />
        }
      />

      {/* Statistiques */}
      <StatistiquesEtudiant 
        etudiants={etudiants} 
        etablissements={etablissements}
        chambres={chambres}
      />

      {/* Filtres avancés */}
      <FiltresAvances titre="Filtres de recherche" collapsible={true} defaultOpen={false}>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium mb-1" style={{ color: colors.textColor }}>
              <FaGraduationCap className="inline mr-2" style={{ color: colors.secondaryColor }} />
              Établissement
            </label>
            <select
              name="n_etab"
              value={filterCriteria.n_etab}
              onChange={handleFilterChange}
              className="w-full p-2 border rounded-md"
              style={{ 
                borderColor: colors.borderColor,
                backgroundColor: colors.inputBg,
                color: colors.textColor
              }}
            >
              <option value="">Tous les établissements</option>
              {etablissements.map((etab) => (
                <option key={etab.n_etab} value={etab.n_etab.toString()}>
                  {etab.nom_etab}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1" style={{ color: colors.textColor }}>
              <FaBed className="inline mr-2" style={{ color: colors.secondaryColor }} />
              Statut de chambre
            </label>
            <select
              name="avecChambre"
              value={filterCriteria.avecChambre}
              onChange={handleFilterChange}
              className="w-full p-2 border rounded-md"
              style={{ 
                borderColor: colors.borderColor,
                backgroundColor: colors.inputBg,
                color: colors.textColor
              }}
            >
              <option value="">Tous les étudiants</option>
              <option value="avec">Avec chambre</option>
              <option value="sans">Sans chambre</option>
            </select>
          </div>
        </div>
      </FiltresAvances>

      {/* Tableau des étudiants */}
      {loading ? (
        <Chargement message="Chargement des étudiants..." />
      ) : error ? (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
          <strong className="font-bold">Erreur!</strong>
          <span className="block sm:inline"> {error}</span>
        </div>
      ) : (
        <Tableau 
          colonnes={colonnesEtudiant} 
          donnees={etudiantsFiltres} 
          onTri={trierDonnees}
          messageVide="Aucun étudiant trouvé"
          actions={(etudiant) => (
            <>
              <BoutonVoir onClick={() => handleView(etudiant)} />
              <BoutonModifier onClick={() => handleEdit(etudiant)} />
              <BoutonSupprimer onClick={() => handleDelete(etudiant.matricule)} />
            </>
          )}
        />
      )}

      {/* Modal de détails */}
      <ModalDetail 
        titre={`Détails de l'étudiant ${selectedEtudiant ? `${selectedEtudiant.prenom} ${selectedEtudiant.nom}` : ''}`}
        contenu={selectedEtudiant && (
          <DetailEtudiant 
            etudiant={selectedEtudiant} 
            getChambreName={getChambreName}
            getEtablissementName={getEtablissementName}
          />
        )}
        visible={showModal}
        onFermer={() => setShowModal(false)}
      />

      {/* Modal de formulaire (ajout/édition) */}
      <ModalFormulaire 
        titre={formMode === 'add' ? 'Ajouter un étudiant' : 'Modifier l\'étudiant'}
        visible={showFormModal}
        onFermer={() => setShowFormModal(false)}
        formulaire={
          <FormulaireEtudiant 
            formData={formData}
            onChange={handleFormChange}
            onSubmit={handleFormSubmit}
            formMode={formMode}
            etablissements={etablissements}
            chambres={chambres}
          />
        }
      />
    </div>
  );
}

export default EtudiantPage;
